INSERT INTO projects (slug, name, category, status, color, summary, description, tech, highlights, links, proof, number) VALUES
('naavis', 'NAAVIS', 'AI SYSTEMS', 'FOUNDING / ACTIVE', 'acid', 'A privacy-first autonomous intelligence system: persistent memory, action, voice, perception, and owner control.', 'NAAVIS is a private, local-first AI platform built from scratch. It combines persistent memory, consent-gated perception, multi-modal interaction (voice, text, vision), action layers, and owner trust controls into a single operator-grade system.', '["Python","Local-first AI","Voice","Privacy","Encrypted Memory"]', '["Encrypted memory and credential store","Consent-gated perception pipeline","On-device / cloud-aware routing","Multi-modal: voice, text, vision","Owner trust and access controls"]', '[]', '["Private system — no public repo","Architecture documented in Signal Journal","Active development"]', '01'),

('aline2', 'ALine2', 'SOCIAL PLATFORM', 'PRODUCTION', 'sky', 'Full-stack social-media platform: web app, backend API, Android app, and superadmin dashboard.', 'ALine2 is a complete social-media ecosystem built under CuboidSoft. It includes a PHP web application, RESTful backend API, native Android app on Google Play Store, and a superadmin dashboard for platform management.', '["PHP","JavaScript","TypeScript","Android","REST API"]', '["Web app with user profiles and content feeds","RESTful backend API layer","Native Android app (Google Play Store)","Superadmin dashboard for platform ops","6 connected repositories"]', '[{"label":"VISIT ALINE2","url":"https://aline2.com"}]', '["Live at aline2.com — HTTP 200","Play Store app published","6 connected repositories"]', '02'),

('tcmone', 'TCMONE', 'ED-TECH PLATFORM', 'PRODUCTION', 'violet', 'Ed-tech platform for virtual and physical classes, labs, and student workflows.', 'TCMONE / thecodemunk.in is a production ed-tech platform under CuboidSoft. It handles virtual and physical classes, labs, student-facing app, internship workflows, and DSA-level learning tracks.', '["PHP","JavaScript","Python","Education","Student App"]', '["Main platform at thecodemunk.in","Student app at app.thecodemunk.in","Internship portal and placement workflows","DSA learning tracks with level progression","6+ repositories in production"]', '[{"label":"VISIT THECODEMUNK.IN","url":"https://thecodemunk.in"}]', '["Live at thecodemunk.in — HTTP 200","6+ repositories in production","Student-facing application"]', '03'),

('davcreations', 'DavCreations', 'COMMERCE PLATFORM', 'PRODUCTION', 'coral', 'Multivendor commerce platform with full CMS, ERP, and HRM modules.', 'DavCreations is a multivendor complex platform built under Shadownik. It includes full CMS, ERP, and HRM modules for vendor management, product catalogs, order processing, and business operations.', '["TypeScript","Commerce","CMS","ERP","HRM"]', '["Multivendor marketplace architecture","CMS for content and vendor storefronts","ERP for financial ops and inventory","HRM for employee and vendor staff management","Full business operations platform"]', '[{"label":"VISIT DAVCREATIONS","url":"https://davcreations.in"}]', '["Live at davcreations.in — HTTP 200","Public GitHub repo available","Full CMS + ERP + HRM modules"]', '04'),

('cuboidpilot', 'CuboidPilot', 'COMPANY OS', 'PRODUCTION', 'acid', 'Company management operating system for CuboidSoft — admin workflows, dashboards, and operational tooling.', 'CuboidPilot is CuboidSoft''s internal company management operating system. Admin workflows, operational dashboards, client management, and business process automation.', '["TypeScript","Operations","Dashboards","Automation"]', '["Real-time operational dashboards","Client onboarding and project tracking","Automated invoicing and reporting","Team coordination and resource allocation","Active production deployment"]', '[]', '["Private CuboidSoft repository","Active production deployment","Full operational tooling"]', '05'),

